    // GoStatus is the status of a goroutine.
    //
    // They correspond directly to the various goroutine states.
    gocpp::string rec::String(GoStatus s)
    {
        //Go switch emulation
        {
            auto condition = s;
            int conditionId = -1;
            if(condition == GoRunnable) { conditionId = 0; }
            else if(condition == GoRunning) { conditionId = 1; }
            else if(condition == GoSyscall) { conditionId = 2; }
            else if(condition == GoWaiting) { conditionId = 3; }
            switch(conditionId)
            {
                case 0:
                    return "Runnable"_s;
                    break;
                case 1:
                    return "Running"_s;
                    break;
                case 2:
                    return "Syscall"_s;
                    break;
                case 3:
                    return "Waiting"_s;
                    break;
            }
        }
        return "Bad"_s;
    }

    // ProcStatus is the status of a P.
    //
    // They mostly correspond to the various P states.
    gocpp::string rec::String(ProcStatus s)
    {
        //Go switch emulation
        {
            auto condition = s;
            int conditionId = -1;
            if(condition == ProcRunning) { conditionId = 0; }
            else if(condition == ProcIdle) { conditionId = 1; }
            else if(condition == ProcSyscall) { conditionId = 2; }
            else if(condition == ProcSyscallAbandoned) { conditionId = 3; }
            switch(conditionId)
            {
                case 0:
                    return "Running"_s;
                    break;
                case 1:
                    return "Idle"_s;
                    break;
                case 2:
                    return "Syscall"_s;
                    break;
                case 3:
                    return "SyscallAbandoned"_s;
                    break;
            }
        }
        return "Bad"_s;
    }

